Interactive Explorer
Use the controls below to filter and compare different training runs in real-time.



Code
viewof selected_exp = Inputs.select(
  [...new Set(research_data.exp_name)], 
  {label: "Experiment", value: research_data.exp_name[0]}
)

viewof selected_dim = Inputs.select(
  [null, ...new Set(research_data.adapter_dim)], 
  {label: "Adapter Dim", format: d =&gt; d === null ? "All" : d}
)

viewof selected_lr = Inputs.select(
  [null, ...new Set(research_data.learning_rate)], 
  {label: "Learning Rate", format: d =&gt; d === null ? "All" : d}
)

viewof min_acc = Inputs.range(
  [0, 1], 
  {label: "Min Accuracy", step: 0.01, value: 0.5}
)

































Training Dynamics


Code
filtered_data = {
  const data = transpose(research_data);
  return data.filter(d =&gt; 
    d.exp_name === selected_exp && 
    (selected_dim === null || d.adapter_dim === selected_dim) &&
    (selected_lr === null || d.learning_rate === selected_lr) &&
    d.accuracy &gt;= min_acc
  );
}

// Interactive Plot using Observable Plot
Plot.plot({
  grid: true,
  color: {legend: true},
  y: {label: "Value"},
  marks: [
    Plot.line(filtered_data, {
      x: "epoch", 
      y: "train_loss", 
      stroke: "full_name", 
      strokeDasharray: "4,4",
      tip: true
    }),
    Plot.line(filtered_data, {
      x: "epoch", 
      y: "val_loss", 
      stroke: "full_name",
      tip: true
    }),
    Plot.dot(filtered_data, {
      x: "epoch", 
      y: "val_loss", 
      fill: "full_name"
    }),
    // Baseline for the plot
    Plot.ruleY([0])
  ]
})


















Run Metadata
Inputs.table(filtered_data, {
  columns: ["full_name", "adapter_dim", "learning_rate", "accuracy", "f1_score", "auroc"],
  header: {
    full_name: "Run ID",
    adapter_dim: "Dim",
    learning_rate: "LR",
    accuracy: "Acc",
    f1_score: "F1",
    auroc: "AUROC"
  }
})





🏆 Performance Ranking


Code
viewof sort_metric = Inputs.select(
  ["accuracy", "f1_score", "auroc"], 
  {label: "Sort By", value: "f1_score"}
)

// Aggregate to final stats per run (latest epoch)
final_stats = {
  const data = transpose(research_data);
  // Filter for only the last epoch available for each run
  const runs = [...new Set(data.map(d =&gt; d.full_name))];
  const last_points = runs.map(name =&gt; {
    const run_points = data.filter(d =&gt; d.full_name === name);
    return run_points.sort((a, b) =&gt; b.epoch - a.epoch)[0];
  });
  // Apply bar plot sorting
  return d3.sort(last_points, (a, b) =&gt; d3.descending(a[sort_metric], b[sort_metric]));
}

Plot.plot({
  marginRight: 120,
  x: {grid: true, label: "Score"},
  y: {label: "Run Name", padding: 0.2},
  color: {scheme: "viridis", label: "Value"},
  marks: [
    Plot.barX(final_stats, {
      y: "full_name", 
      x: sort_metric, 
      fill: sort_metric,
      tip: true
    }),
    Plot.ruleX([0])
  ]
})

