Plot.plot({
  grid: true,
  aspectRatio: 1,
  x: {label: "False Positive Rate (FPR)", domain: [0, 1]},
  y: {label: "True Positive Rate (TPR)", domain: [0, 1]},
  color: {legend: true},
  marks: [
    Plot.line([0, 1], {x: d =&gt; d, y: d =&gt; d, stroke: "#ccc", strokeDasharray: "4,4"}), // Random chance line
    Plot.line(filtered_roc, {
      x: "fpr", 
      y: "tpr", 
      stroke: "class",
      tip: true
    })
  ]
})
































